# Isotope analysis, step 4: literature d15N endmember database.
#
# Writes: data/isotope_endmember_literature.csv, data/isotope_fractionation_literature.csv
#
# Rules used when building this file
# - Only values that were read in the cited source (or, where stated in `verification`,
#   reported inside another source I read) are entered. Nothing is estimated or recalled.
# - d15N is per mil vs air N2. Blank = not reported in the text I read.
# - Ranges are stored as d15N_min / d15N_max. Standard deviations are only stored when the
#   source reports them; SDs derived from ranges are computed in the report, never here.
# - `value_class` separates direct source compositions from transformed or mixed samples.
#   Only `use_in_prior == TRUE` rows feed the priors.
# - `verification`: "read_primary_text" = I read the value in the paper/report text
#   (USGS SIR 2009-5253 values were checked against the PDF text); "read_via_page_summary" =
#   obtained through a web-page summary tool and not yet cross-checked against the PDF;
#   "reported_in_secondary" = quoted by a paper I read, original not read.

library(tidyverse)
library(here)

e <- function(entry_id, prior_group, source_category, n_pool, sample_type, location,
              d15N_mean = NA, d15N_sd = NA, d15N_min = NA, d15N_max = NA, n = NA,
              value_class, use_in_prior, study, year, doi = NA, verification, notes = "") {
  tibble(entry_id, prior_group, source_category, n_pool, sample_type, location,
         d15N_mean, d15N_sd, d15N_min, d15N_max, n, value_class, use_in_prior,
         study, year, doi, verification, notes)
}

